	new fwCure    = CreateMultiForward("zp_fw_core_cure_post",    ET_IGNORE, FP_CELL, FP_CELL)
	new fwRoundSt = CreateMultiForward("zp_fw_gamemodes_start",   ET_IGNORE, FP_CELL)
	new fwRoundEn = CreateMultiForward("zp_fw_gamemodes_end",     ET_IGNORE, FP_CELL)

	// Ham hooks for kills/damage
	RegisterHam(Ham_TakeDamage, "player", "Ham_TakeDamage_Post", 1)
