// ─── Player lifecycle ───────────────────────────────────────────────────────
public client_connect(id)
{
	g_PlayerUserId[id] = 0
	// Stats will be zero-initialized by AMXX runtime; no need to clear
	log_to_file("zp_round_stats.log", "#%d client_connect (userid pending)", id)
}

public client_putinserver(id)
{
	g_PlayerUserId[id] = get_user_userid(id)

	// Load persistent stats from vault if enabled
	if (get_pcvar_num(g_cvar_save_maps) && g_PlayerUserId[id] != 0)
	{
		load_player_stats(id)
	}

	log_to_file("zp_round_stats.log", "#%d putinserver userid=%d", id, g_PlayerUserId[id])
}

public client_disconnect(id)
{
	// Save stats before player leaves
	if (get_pcvar_num(g_cvar_save_maps) && g_PlayerUserId[id] != 0)
	{
		save_player_stats(id)
	}

	// Clear all stored data for this slot
	g_PlayerUserId[id] = 0

	for (new i = 0; i < SP_STATS_COUNT; i++)
	{
		g_PlayerStats[id][i] = 0
	}

	// Clear round stats too
	new roundSize = SP_STATS_COUNT - 6
	for (new i = 0; i < roundSize; i++)
	{
		g_RoundStats[id][i] = 0
	}

	log_to_file("zp_round_stats.log", "#%d disconnect — stats saved and slot cleared", id)
}

// ─── Ham hooks ───────────────────────────────────────────────────────────────
public Ham_TakeDamage_Post(victim, inflictor, attacker, Float:damage, damagetype)
{
	if (!is_user_connected(attacker) || !is_user_alive(victim))
		return HAM_IGNORED

	if (attacker > maxclients || attacker < 1)
		return HAM_IGNORED

	// World damage (lava, fall, trigger_hurt)
	if (attacker == 0 || !is_user_connected(attacker))
	{
		if (get_pcvar_num(g_cvar_track_world))
		{
			// Track damage taken from world
			new vid = victim
			g_PlayerStats[vid][SP_DAMAGED_TAKEN] += floatround(damage)
			g_RoundStats[vid][SP_ROUND_DAMAGE_TAKEN] += floatround(damage)
		}
		return HAM_IGNORED
	}

	// Player vs player damage
	new atk = attacker
	new vic = victim

	// Update damage done by attacker
	g_PlayerStats[atk][SP_DAMAGED_DONE] += floatround(damage)
	g_RoundStats[atk][SP_ROUND_DAMAGE_DONE] += floatround(damage)

	// Update damage taken by victim
	g_PlayerStats[vic][SP_DAMAGED_TAKEN] += floatround(damage)
	g_RoundStats[vic][SP_ROUND_DAMAGE_TAKEN] += floatround(damage)

	return HAM_IGNORED
}

public Ham_Killed_Post(victim, attacker, shouldgib)
{
	if (!is_user_connected(attacker) && attacker != 0)
		return HAM_IGNORED

	// Increment victim deaths
	g_PlayerStats[victim][SP_DEATHS]++
	g_RoundStats[victim][SP_ROUND_DEATHS]++

	// Team deaths
	new vicTeam = get_user_team(victim)
	if (vicTeam == CS_TEAM_T)
		g_TeamRoundStats[0][ST_DEATHS]++
	else if (vicTeam == CS_TEAM_CT)
		g_TeamRoundStats[1][ST_DEATHS]++

	// Handle killer stats
	if (attacker && is_user_connected(attacker) && attacker != victim)
	{
		// Attacker gets a kill
		g_PlayerStats[attacker][SP_KILLS]++
		g_RoundStats[attacker][SP_ROUND_KILLS]++

		// Team kills
		new atkTeam = get_user_team(attacker)
		if (atkTeam == CS_TEAM_T)
			g_TeamRoundStats[0][ST_KILLS]++
		else if (atkTeam == CS_TEAM_CT)
			g_TeamRoundStats[1][ST_KILLS]++

		// Check for headshot
		new health = get_user_health(victim)
		if (health <= 0)
		{
			// This is handled in DeathMsg event for weapon/hs info
		}

		// Fire forward
		ExecuteForward(fw_player_killed, 0, victim, attacker, "", is_user_zombie(attacker))
	}
	else if (attacker == victim)
	{
		// Suicide
		if (get_pcvar_num(g_cvar_count_suicide))
		{
			g_PlayerStats[victim][SP_DEATHS]++
			g_RoundStats[victim][SP_ROUND_DEATHS]++
		}
	}
	else if (attacker == 0)
	{
		// World kill (lava, fall)
		if (get_pcvar_num(g_cvar_count_self_death))
		{
			g_PlayerStats[victim][SP_DEATHS]++
			g_RoundStats[victim][SP_ROUND_DEATHS]++
		}
	}

	return HAM_IGNORED
}

public Ham_Spawn_Post(id)
{
	if (!is_user_alive(id))
		return HAM_IGNORED

	// On spawn, check if player should be tracked as zombie/human for infection counting
	// Infection count is tracked via ZP forward, not spawn
	return HAM_IGNORED
}

// ─── ZP Forwards ─────────────────────────────────────────────────────────────
public zp_fw_core_infect_post(id, attacker)
{
	// id is now a zombie
	g_PlayerStats[id][SP_INFECTED]++
	g_RoundStats[id][SP_ROUND_INFECTED]++

	// Attacker (zombie) gets an infection stat if different
	if (attacker && attacker != id && is_user_connected(attacker))
	{
		// The infecting zombie's infection count is already incremented
		// when THEY were infected. We don't double-count.
	}

	// Fire forward
	new :fw = CreateMultiForward("zp_stats_fw_player_infected", ET_IGNORE, FP_CELL, FP_CELL)
	ExecuteForward(fw, 0, id, attacker)
	DeleteForward(fw)

	log_to_file("zp_round_stats.log", "#%d infected by #%d", id, attacker)
}

public zp_fw_core_cure_post(id, attacker)
{
	// Forward for cure event (no separate stat, but good for extension)
	new :fw = CreateMultiForward("zp_stats_fw_player_cured", ET_IGNORE, FP_CELL, FP_CELL)
	ExecuteForward(fw, 0, id, attacker)
	DeleteForward(fw)
}

public zp_fw_gamemodes_start(game_mode_id)
{
	g_RoundPhase = RP_FREEZE
	g_MapRounds++
	g_RoundNumber++

	// Fire round start forward
	new :fw = CreateMultiForward("zp_stats_fw_round_start", ET_IGNORE)
	ExecuteForward(fw, 0)
	DeleteForward(fw)

	log_to_file("zp_round_stats.log", "Round %d start (phase=freeze)", g_RoundNumber)
}

public zp_fw_gamemodes_end(game_mode_id)
{
	g_RoundPhase = RP_END

	// Determine winner and update team wins
	new winner = 2 // draw
	if (zp_core_get_zombie_count() == 0)
	{
		winner = 1 // CT/humans win
		g_TeamRoundStats[1][ST_ROUND_WINS]++
	}
	else if (zp_core_get_human_count() == 0)
	{
		winner = 0 // T/zombies win
		g_TeamRoundStats[0][ST_ROUND_WINS]++
	}

	// Fire round end forward
	new :fw = CreateMultiForward("zp_stats_fw_round_end", ET_IGNORE, FP_CELL)
	ExecuteForward(fw, 0, winner)
	DeleteForward(fw)

	log_to_file("zp_round_stats.log", "Round %d end (winner=%d)", g_RoundNumber, winner)
}

// ─── AMXX Events ─────────────────────────────────────────────────────────────
public event_death()
{
	new killer   = read_data(1)
	new victim   = read_data(2)
	new headshot = read_data(3)
	new weapon[32]
	read_data(4, weapon, charsmax(weapon))

	// Validate
	if (!is_user_connected(victim) || !is_user_connected(killer))
		return PLUGIN_CONTINUE

	if (killer == victim)
		return PLUGIN_CONTINUE

	// Headshot tracking
	if (headshot)
	{
		g_PlayerStats[killer][SP_HEADSHOTS]++
		g_RoundStats[killer][SP_ROUND_HEADSHOTS]++
	}

	// Kill already counted in Ham_Killed_Post, but we track weapon here for diagnostics
	log_to_file("zp_round_stats.log", "#%d kills #%d with %s", killer, victim, weapon)

	return PLUGIN_CONTINUE
}

public event_round_start()
{
	// Detect actual round start vs game restart
	new textmsg[32]
	read_data(2, textmsg, charsmax(textmsg))

	if (equal(textmsg, "#Game_Commencing"))
	{
		// Full game restart — reset everything
		reset_all_stats()
		g_RoundNumber = 0
		g_MapRounds = 0
	}
	else if (equal(textmsg, "#Game_will_restart_in"))
	{
		// Restart countdown — don't reset yet
	}
	else
	{
		// Regular round start
		if (get_pcvar_num(g_cvar_auto_reset))
		{
			reset_round_stats()
		}
	}

	g_RoundPhase = RP_PLAYING
	return PLUGIN_CONTINUE
}

public event_round_end()
{
	new textmsg[32]
	read_data(2, textmsg, charsmax(textmsg))

	// Determine winner from audio event
	new winner = 2 // draw
	if (equal(textmsg, "#Terrorists_Win"))
		winner = 0
	else if (equal(textmsg, "#CTs_Win"))
		winner = 1
	// #Round_Draw stays 2

	log_to_file("zp_round_stats.log", "Round end event: winner=%d", winner)
}

