public native_get_round_phase()            { return g_RoundPhase }
public native_get_round_number()           { return g_RoundNumber }
public native_get_map_rounds()             { return g_MapRounds }
public native_reset_user(id)
{
	if (!is_user_connected(id)) return
	for (new i = 0; i < SP_STATS_COUNT; i++)
	{
		g_PlayerStats[id][i] = 0
		g_RoundStats[id][i] = 0
	}
}
public native_reset_round()
{
	reset_round_stats()
}
public native_get_stats_count()
{
	return SP_STATS_COUNT
}

