/*
 * Round & Player Statistics Manager for Zombie Plague 5.0.8a
 *
 * Tracks per-player and per-team statistics across rounds and maps.
 * Displays a MOTD window at the end of each round with stats for both
 * Terrorist (zombie) and Counter-Terrorist (human) sides.
 *
 * Natives for other plugins:
 *   zp_stats_get_user_kills(id)
 *   zp_stats_get_user_deaths(id)
 *   zp_stats_get_user_infected(id)
 *   zp_stats_get_user_damage_done(id)
 *   zp_stats_get_user_damage_taken(id)
 *   zp_stats_get_user_headshots(id)
 *   zp_stats_get_user_round_kills(id)
 *   zp_stats_get_user_round_deaths(id)
 *   zp_stats_get_user_round_infected(id)
 *   zp_stats_get_user_round_damage_done(id)
 *   zp_stats_get_user_round_damage_taken(id)
 *   zp_stats_get_user_round_headshots(id)
 *   zp_stats_get_team_round_kills(team)
 *   zp_stats_get_team_round_deaths(team)
 *   zp_stats_get_team_round_wins(team)
 *   zp_stats_get_round_phase()
 *   zp_stats_get_round_number()
 *   zp_stats_get_map_rounds()
 *   zp_stats_reset_user(id)
 *   zp_stats_reset_round()
 *   zp_stats_get_stats_count()
 *
 * Forwards for other plugins:
 *   zp_stats_fw_player_killed(victim, attacker, const weapon[], is_zombie_kill)
 *   zp_stats_fw_player_infected(id, attacker)
 *   zp_stats_fw_player_cured(id, attacker)
 *   zp_stats_fw_round_start()
 *   zp_stats_fw_round_end(winner_team)
 */

#include <amxmodx>
#include <amxmisc>
#include <cstrike>
#include <fakemeta>
#include <hamsandwich>
#include <cs_ham_bots_api>
#include <nvault>
#include <zp50_core>
#include <zp50_gamemodes>

#if AMXX_VERSION_NUM < 175
	#error "Requires AMX Mod X 1.75+"
#endif

// ─── Constants ───────────────────────────────────────────────────────────────
#define PLUGIN    "[ZP] Round Stats"
#define VERSION   "1.0.0"
#define AUTHOR    "Agnes/AI"

#define MAX_NAME_LENGTH  32
#define VAULT_KEY_PREFIX "zprs_"
#define VAULT_FILE       "zp_round_stats"

// Chat prefix color code
#define PREFIX "^x04[ZP Stats]^x01"

// ─── Stat indices ────────────────────────────────────────────────────────────
enum _:STATS_PLAYER
{
	SP_KILLS,
	SP_DEATHS,
	SP_INFECTED,
	SP_DAMAGED_DONE,
	SP_DAMAGED_TAKEN,
	SP_HEADSHOTS,
	SP_ROUND_KILLS,
	SP_ROUND_DEATHS,
	SP_ROUND_INFECTED,
	SP_ROUND_DAMAGE_DONE,
	SP_ROUND_DAMAGE_TAKEN,
	SP_ROUND_HEADSHOTS,
	SP_STATS_COUNT
}

enum _:STATS_TEAM
{
	ST_KILLS,
	ST_DEATHS,
	ST_ROUND_WINS,
	ST_STATS_COUNT
}

enum _:ROUND_PHASE
{
	RP_NONE = 0,
	RP_FREEZE,
	RP_PLAYING,
	RP_END
}

// ─── Globals ─────────────────────────────────────────────────────────────────
new g_PlayerStats[MAX_PLAYERS + 1][SP_STATS_COUNT]
new g_RoundStats[MAX_PLAYERS + 1][SP_STATS_COUNT]
new g_TeamRoundStats[2][ST_STATS_COUNT]

new g_RoundPhase
new g_RoundNumber
new g_MapRounds

new g_Vault
new g_HudSyncRound
new g_HudSyncMap

new g_PlayerUserId[MAX_PLAYERS + 1]

new g_fwPlayerKilled
new g_fwPlayerInfected
new g_fwPlayerCured
new g_fwRoundStart
new g_fwRoundEnd

// CVARs
new g_cvar_save_maps
new g_cvar_auto_reset
new g_cvar_count_self_death
new g_cvar_count_suicide
new g_cvar_track_world

// ─── Plugin info ─────────────────────────────────────────────────────────────
public plugin_init()
{
	register_plugin(PLUGIN, VERSION, AUTHOR)

	// Register events
	register_event("DeathMsg",   "event_death",      "a")
	register_event("SendAudio",  "event_round_end",  "a", "2=%!MRAD_terwin", "2=%!MRAD_ctwin", "2=%!MRAD_rounddraw")
	register_event("ResetHUD",   "event_reset_hud",  "b")
	register_event("TextMsg",    "event_textmsg",    "a")

	// Register Ham hooks
	RegisterHam(Ham_TakeDamage, "player", "Ham_TakeDamage_Post", 1)
	RegisterHamBots(Ham_TakeDamage, "Ham_TakeDamage_Post", 1)
	RegisterHam(Ham_Killed, "player", "Ham_Killed_Post", 1)
	RegisterHamBots(Ham_Killed, "Ham_Killed_Post", 1)
	RegisterHam(Ham_Spawn, "player", "Ham_Spawn_Post", 1)
	RegisterHamBots(Ham_Spawn, "Ham_Spawn_Post", 1)

	// Create HUD sync objects
	g_HudSyncRound = CreateHudSyncObj()
	g_HudSyncMap   = CreateHudSyncObj()

	// Initialize round state
	g_RoundPhase     = RP_NONE
	g_RoundNumber    = 0
	g_MapRounds      = 0

	// Open vault
	g_Vault = nvault_open(VAULT_FILE)
	if (g_Vault == INVALID_HANDLE)
	{
		log_to_file("zp_round_stats.log", "[ZP RS] ERROR: Could not open vault '%s'", VAULT_FILE)
	}
	else
	{
		log_to_file("zp_round_stats.log", "[ZP RS] Vault opened successfully")
	}
}

public plugin_cfg()
{
	g_cvar_save_maps     = create_cvar("zp_stats_save_maps",     "1", FCVAR_SERVER, "Save stats between maps")
	g_cvar_auto_reset    = create_cvar("zp_stats_auto_reset",    "1", FCVAR_SERVER, "Auto-reset round stats on round start")
	g_cvar_count_self_death = create_cvar("zp_stats_self_death", "1", FCVAR_SERVER, "Count self-inflicted deaths")
	g_cvar_count_suicide    = create_cvar("zp_stats_suicide",    "1", FCVAR_SERVER, "Count suicides")
	g_cvar_track_world      = create_cvar("zp_stats_world_dmg",  "1", FCVAR_SERVER, "Track world/lava damage")
}

public plugin_natives()
{
	// Create forwards
	g_fwPlayerKilled  = CreateMultiForward("zp_stats_fw_player_killed",  ET_IGNORE, FP_CELL, FP_CELL, FP_STRING, FP_CELL)
	g_fwPlayerInfected = CreateMultiForward("zp_stats_fw_player_infected", ET_IGNORE, FP_CELL, FP_CELL)
	g_fwPlayerCured   = CreateMultiForward("zp_stats_fw_player_cured",    ET_IGNORE, FP_CELL, FP_CELL)
	g_fwRoundStart    = CreateMultiForward("zp_stats_fw_round_start",     ET_IGNORE)
	g_fwRoundEnd      = CreateMultiForward("zp_stats_fw_round_end",       ET_IGNORE, FP_CELL)

	register_library("zp50_round_stats")

	register_native("zp_stats_get_user_kills",             "native_get_user_kills")
	register_native("zp_stats_get_user_deaths",            "native_get_user_deaths")
	register_native("zp_stats_get_user_infected",          "native_get_user_infected")
	register_native("zp_stats_get_user_damage_done",       "native_get_user_damage_done")
	register_native("zp_stats_get_user_damage_taken",      "native_get_user_damage_taken")
	register_native("zp_stats_get_user_headshots",         "native_get_user_headshots")
	register_native("zp_stats_get_user_round_kills",       "native_get_user_round_kills")
	register_native("zp_stats_get_user_round_deaths",      "native_get_user_round_deaths")
	register_native("zp_stats_get_user_round_infected",    "native_get_user_round_infected")
	register_native("zp_stats_get_user_round_damage_done", "native_get_user_round_damage_done")
	register_native("zp_stats_get_user_round_damage_taken","native_get_user_round_damage_taken")
	register_native("zp_stats_get_user_round_headshots",   "native_get_user_round_headshots")
	register_native("zp_stats_get_team_round_kills",       "native_get_team_round_kills")
	register_native("zp_stats_get_team_round_deaths",      "native_get_team_round_deaths")
	register_native("zp_stats_get_team_round_wins",        "native_get_team_round_wins")
	register_native("zp_stats_get_round_phase",            "native_get_round_phase")
	register_native("zp_stats_get_round_number",           "native_get_round_number")
	register_native("zp_stats_get_map_rounds",             "native_get_map_rounds")
	register_native("zp_stats_reset_user",                 "native_reset_user")
	register_native("zp_stats_reset_round",                "native_reset_round")
	register_native("zp_stats_get_stats_count",            "native_get_stats_count")
}

public plugin_precache()
{
	log_to_file("zp_round_stats.log", "[ZP RS] plugin_precache done")
}

public plugin_end()
{
	save_all_player_stats()
	if (g_Vault != INVALID_HANDLE)
		nvault_close(g_Vault)
	log_to_file("zp_round_stats.log", "[ZP RS] plugin_end done")
}

// ═════════════════════════════════════════════════════════════════════════════
// ZP Forwards
// ═════════════════════════════════════════════════════════════════════════════

public zp_fw_core_infect_post(id, attacker)
{
	g_PlayerStats[id][SP_INFECTED]++
	g_RoundStats[id][SP_ROUND_INFECTED]++

	if (g_fwPlayerInfected != -1)
		ExecuteForward(g_fwPlayerInfected, 0, id, attacker)

	log_to_file("zp_round_stats.log", "[ZP RS] #%d infected by #%d", id, attacker)
}

public zp_fw_core_cure_post(id, attacker)
{
	if (g_fwPlayerCured != -1)
		ExecuteForward(g_fwPlayerCured, 0, id, attacker)
}

public zp_fw_gamemodes_start(game_mode_id)
{
	g_RoundPhase = RP_FREEZE
	g_MapRounds++
	g_RoundNumber++

	if (g_fwRoundStart != -1)
		ExecuteForward(g_fwRoundStart, 0)

	log_to_file("zp_round_stats.log", "[ZP RS] Round %d start (phase=freeze, mode=%d)", g_RoundNumber, game_mode_id)
}

public zp_fw_gamemodes_end(game_mode_id)
{
	g_RoundPhase = RP_END

	// Determine winner based on remaining zombies/humans
	new winner = 2 // draw
	if (zp_core_get_zombie_count() == 0)
	{
		winner = 1 // CT/humans win
		g_TeamRoundStats[1][ST_ROUND_WINS]++
	}
	else if (zp_core_get_human_count() == 0)
	{
		winner = 0 // T/zombies win
		g_TeamRoundStats[0][ST_ROUND_WINS]++
	}

	if (g_fwRoundEnd != -1)
		ExecuteForward(g_fwRoundEnd, 0, winner)

	// Show MOTD with stats
	show_round_stats_menu()

	log_to_file("zp_round_stats.log", "[ZP RS] Round %d end (winner=%d, mode=%d)", g_RoundNumber, winner, game_mode_id)
}

// ═════════════════════════════════════════════════════════════════════════════
// Player Lifecycle
// ═════════════════════════════════════════════════════════════════════════════

public client_connect(id)
{
	g_PlayerUserId[id] = 0
	log_to_file("zp_round_stats.log", "[ZP RS] #%d client_connect (userid pending)", id)
}

public client_putinserver(id)
{
	g_PlayerUserId[id] = get_user_userid(id)

	// Load persistent stats from vault if enabled
	if (get_pcvar_num(g_cvar_save_maps) && g_PlayerUserId[id] != 0)
	{
		load_player_stats(id)
	}

	log_to_file("zp_round_stats.log", "[ZP RS] #%d putinserver userid=%d", id, g_PlayerUserId[id])
}

public client_disconnected(id)
{
	// Save stats before player leaves
	if (get_pcvar_num(g_cvar_save_maps) && g_PlayerUserId[id] != 0)
	{
		save_player_stats(id)
	}

	// Clear all stored data for this slot
	g_PlayerUserId[id] = 0

	for (new i = 0; i < SP_STATS_COUNT; i++)
	{
		g_PlayerStats[id][i] = 0
		g_RoundStats[id][i] = 0
	}

	log_to_file("zp_round_stats.log", "[ZP RS] #%d disconnected — stats saved and slot cleared", id)
}

// ═════════════════════════════════════════════════════════════════════════════
// Ham Hooks
// ═════════════════════════════════════════════════════════════════════════════

public Ham_TakeDamage_Post(victim, inflictor, attacker, Float:damage, damagetype)
{
	if (!is_user_connected(victim) || !is_user_alive(victim))
		return HAM_IGNORED

	new atk = attacker

	// Player vs player damage
	if (atk >= 1 && atk <= maxplayers && is_user_connected(atk))
	{
		g_PlayerStats[atk][SP_DAMAGED_DONE] += floatround(damage)
		g_RoundStats[atk][SP_ROUND_DAMAGE_DONE] += floatround(damage)

		g_PlayerStats[victim][SP_DAMAGED_TAKEN] += floatround(damage)
		g_RoundStats[victim][SP_ROUND_DAMAGE_TAKEN] += floatround(damage)
	}
	// World damage (lava, fall, trigger_hurt)
	else if (get_pcvar_num(g_cvar_track_world))
	{
		g_PlayerStats[victim][SP_DAMAGED_TAKEN] += floatround(damage)
		g_RoundStats[victim][SP_ROUND_DAMAGE_TAKEN] += floatround(damage)
	}

	return HAM_IGNORED
}

public Ham_Killed_Post(victim, attacker, shouldgib)
{
	new atk = attacker
	new vic = victim

	// Valid attacker (other player)
	if (atk >= 1 && atk <= maxplayers && is_user_connected(atk) && atk != vic)
	{
		// Increment kill and death stats
		g_PlayerStats[vic][SP_DEATHS]++
		g_RoundStats[vic][SP_ROUND_DEATHS]++

		g_PlayerStats[atk][SP_KILLS]++
		g_RoundStats[atk][SP_ROUND_KILLS]++

		// Team stats
		new vicTeam = get_user_team(vic)
		if (vicTeam == CS_TEAM_T)
			g_TeamRoundStats[0][ST_DEATHS]++
		else if (vicTeam == CS_TEAM_CT)
			g_TeamRoundStats[1][ST_DEATHS]++

		new atkTeam = get_user_team(atk)
		if (atkTeam == CS_TEAM_T)
			g_TeamRoundStats[0][ST_KILLS]++
		else if (atkTeam == CS_TEAM_CT)
			g_TeamRoundStats[1][ST_KILLS]++

		// Fire forward
		if (g_fwPlayerKilled != -1)
			ExecuteForward(g_fwPlayerKilled, 0, vic, atk, "", zp_core_is_zombie(atk) ? 1 : 0)
	}
	// Suicide
	else if (atk == vic)
	{
		if (get_pcvar_num(g_cvar_count_suicide))
		{
			g_PlayerStats[vic][SP_DEATHS]++
			g_RoundStats[vic][SP_ROUND_DEATHS]++

			new vicTeam = get_user_team(vic)
			if (vicTeam == CS_TEAM_T)
				g_TeamRoundStats[0][ST_DEATHS]++
			else if (vicTeam == CS_TEAM_CT)
				g_TeamRoundStats[1][ST_DEATHS]++
		}
	}
	// World kill (lava, fall, etc.)
	else if (atk == 0)
	{
		if (get_pcvar_num(g_cvar_count_self_death))
		{
			g_PlayerStats[vic][SP_DEATHS]++
			g_RoundStats[vic][SP_ROUND_DEATHS]++

			new vicTeam = get_user_team(vic)
			if (vicTeam == CS_TEAM_T)
				g_TeamRoundStats[0][ST_DEATHS]++
			else if (vicTeam == CS_TEAM_CT)
				g_TeamRoundStats[1][ST_DEATHS]++
		}
	}

	return HAM_IGNORED
}

public Ham_Spawn_Post(id)
{
	if (!is_user_alive(id))
		return HAM_IGNORED
	return HAM_IGNORED
}

// ═════════════════════════════════════════════════════════════════════════════
// AMXX Events
// ═════════════════════════════════════════════════════════════════════════════

public event_death()
{
	new killer   = read_data(1)
	new victim   = read_data(2)
	new headshot = read_data(3)
	new weapon[32]
	read_data(4, weapon, charsmax(weapon))

	// Validate
	if (!is_user_connected(victim) || !is_user_connected(killer))
		return PLUGIN_CONTINUE

	if (killer == victim)
		return PLUGIN_CONTINUE

	// Headshot tracking
	if (headshot)
	{
		g_PlayerStats[killer][SP_HEADSHOTS]++
		g_RoundStats[killer][SP_ROUND_HEADSHOTS]++
	}

	log_to_file("zp_round_stats.log", "[ZP RS] #%d kills #%d with %s", killer, victim, weapon)
	return PLUGIN_CONTINUE
}

public event_textmsg()
{
	new textmsg[32]
	read_data(2, textmsg, charsmax(textmsg))

	if (equal(textmsg, "#Game_Commencing"))
	{
		// Full game restart — reset everything
		reset_all_stats()
		g_RoundNumber = 0
		g_MapRounds = 0
	}
	else if (equal(textmsg, "#Game_will_restart_in"))
	{
		// Restart countdown — do not reset yet
	}
	else
	{
		// Regular round start
		if (get_pcvar_num(g_cvar_auto_reset))
			reset_round_stats()
	}

	g_RoundPhase = RP_PLAYING
	return PLUGIN_CONTINUE
}

public event_round_end()
{
	new textmsg[32]
	read_data(2, textmsg, charsmax(textmsg))

	new winner = 2 // draw
	if (equal(textmsg, "#Terrorists_Win"))
		winner = 0
	else if (equal(textmsg, "#CTs_Win"))
		winner = 1

	log_to_file("zp_round_stats.log", "[ZP RS] Round end event: winner=%d", winner)
	return PLUGIN_CONTINUE
}

public event_reset_hud(id)
{
	// ResetHUD fires on every spawn — round stats are cleared on round start via event_textmsg
}

// ═════════════════════════════════════════════════════════════════════════════
// Menu System
// ═════════════════════════════════════════════════════════════════════════════

enum _:MENU_STATE
{
	MENU_NONE = 0,
	MENU_PLAYER_STATS,
	MENU_ALL_STATS
}

new g_MenuState[MAX_PLAYERS + 1]
new g_MenuPage[MAX_PLAYERS + 1]

show_round_stats_menu()
{
	new menu[1024]
	new len = 0
	new name[MAX_NAME_LENGTH]
	new players[maxplayers], pcount, p
	new pname[MAX_NAME_LENGTH]
	new totalKills = 0
	new totalDeaths = 0
	new totalInfected = 0
	new totalDamage = 0
	new totalHeadshots = 0

	// Calculate totals
	for (p = 1; p <= maxplayers; p++)
	{
		if (!is_user_connected(p))
			continue
		totalKills    += g_PlayerStats[p][SP_KILLS]
		totalDeaths   += g_PlayerStats[p][SP_DEATHS]
		totalInfected += g_PlayerStats[p][SP_INFECTED]
		totalDamage   += g_PlayerStats[p][SP_DAMAGED_DONE]
		totalHeadshots += g_PlayerStats[p][SP_HEADSHOTS]
	}

	len += formatex(menu[len], charsmax(menu) - len, '<meta charset="utf-8">')
	len += formatex(menu[len], charsmax(menu) - len, '<body bgcolor="#1a1a2e" style="color:#eee; font-family:monospace; padding:20px;">')
	len += formatex(menu[len], charsmax(menu) - len, '<h2 style="color:#e94560; text-align:center;">[ZP] Round Statistics</h2>')
	len += formatex(menu[len], charsmax(menu) - len, '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse; width:100%%; margin:10px 0;">')
	len += formatex(menu[len], charsmax(menu) - len, '<tr style="background:#16213e;">')
	len += formatex(menu[len], charsmax(menu) - len, '<th>#</th><th>Player</th><th>Kills</th><th>Deaths</th><th>HS</th><th>Infect</th><th>Dmg Done</th><th>Dmg Taken</th>')
	len += formatex(menu[len], charsmax(menu) - len, '</tr>')

	// Sort players by kills (simple bubble sort)
	new sortedPlayers[maxplayers]
	new sortedKills[maxplayers]
	new count = 0
	for (p = 1; p <= maxplayers; p++)
	{
		if (!is_user_connected(p))
			continue
		sortedPlayers[count] = p
		sortedKills[count] = g_PlayerStats[p][SP_KILLS]
		count++
	}
	// Bubble sort descending by kills
	for (new i = 0; i < count - 1; i++)
	{
		for (new j = 0; j < count - 1 - i; j++)
		{
			if (sortedKills[j] < sortedKills[j + 1])
			{
				new temp = sortedKills[j]
				sortedKills[j] = sortedKills[j + 1]
				sortedKills[j + 1] = temp
				temp = sortedPlayers[j]
				sortedPlayers[j] = sortedPlayers[j + 1]
				sortedPlayers[j + 1] = temp
			}
		}
	}

	// Table rows
	for (p = 0; p < count; p++)
	{
		new pid = sortedPlayers[p]
		get_user_name(pid, pname, charsmax(pname))
		// Escape HTML special characters
	replace(pname, charsmax(pname), "<", "&#60;")
		replace(pname, charsmax(pname), ">", "&#62;")
		new bgColor = (p % 2 == 0) ? "#1a1a2e" : "#16213e"
		len += formatex(menu[len], charsmax(menu) - len, '<tr style="background:%s;">', bgColor)
		len += formatex(menu[len], charsmax(menu) - len, '<td>%d</td>', p + 1)
		len += formatex(menu[len], charsmax(menu) - len, '<td>%s</td>', pname)
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#0f0;">%d</td>', g_PlayerStats[pid][SP_KILLS])
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#f55;">%d</td>', g_PlayerStats[pid][SP_DEATHS])
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#ff0;">%d</td>', g_PlayerStats[pid][SP_HEADSHOTS])
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#f0f;">%d</td>', g_PlayerStats[pid][SP_INFECTED])
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#0ff;">%d</td>', g_PlayerStats[pid][SP_DAMAGED_DONE])
		len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#fa0;">%d</td>', g_PlayerStats[pid][SP_DAMAGED_TAKEN])
		len += formatex(menu[len], charsmax(menu) - len, '</tr>')
	}

	// Totals row
	len += formatex(menu[len], charsmax(menu) - len, '<tr style="background:#0f3460; font-weight:bold;">')
	len += formatex(menu[len], charsmax(menu) - len, '<td>-</td><td>TOTAL</td>')
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#0f0;">%d</td>', totalKills)
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#f55;">%d</td>', totalDeaths)
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#ff0;">%d</td>', totalHeadshots)
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#f0f;">%d</td>', totalInfected)
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#0ff;">%d</td>', totalDamage)
	len += formatex(menu[len], charsmax(menu) - len, '<td style="color:#fa0;">-</td>')
	len += formatex(menu[len], charsmax(menu) - len, '</tr>')
	len += formatex(menu[len], charsmax(menu) - len, '</table>')

	// Round info
	len += formatex(menu[len], charsmax(menu) - len, '<div style="margin-top:15px; padding:10px; background:#16213e; border-radius:5px;">')
	len += formatex(menu[len], charsmax(menu) - len, '<b>Round Info:</b><br>')
	len += formatex(menu[len], charsmax(menu) - len, 'Round: %d / Map rounds: %d<br>', g_RoundNumber, g_MapRounds)
	len += formatex(menu[len], charsmax(menu) - len, 'T (Zombies) wins: %d | CT (Humans) wins: %d', g_TeamRoundStats[0][ST_ROUND_WINS], g_TeamRoundStats[1][ST_ROUND_WINS])
	len += formatex(menu[len], charsmax(menu) - len, '</div>')

	len += formatex(menu[len], charsmax(menu) - len, '<div style="margin-top:10px; font-size:12px; color:#888; text-align:center;">')
	len += formatex(menu[len], charsmax(menu) - len, '[ZP] Round Statistics v%s | AMX Mod X %s', VERSION, AMXX_VERSION_STR)
	len += formatex(menu[len], charsmax(menu) - len, '</div>')

	len += formatex(menu[len], charsmax(menu) - len, '</body></html>')

	// Show to all connected players
	new iPlayers[maxplayers], iCount
	get_players(iPlayers, iCount)
	for (p = 0; p < iCount; p++)
	{
		show_motd(iPlayers[p], menu, sprintf("Round Stats - Round %d", g_RoundNumber))
	}
}

show_player_stats_menu(id, page)
{
	if (!is_user_connected(id))
		return

	g_MenuState[id] = MENU_PLAYER_STATS
	g_MenuPage[id] = page

	new menu[512]
	new len = 0
	get_user_name(id, menu, charsmax(menu))

	len += formatex(menu[len], charsmax(menu) - len, "^n^n\y%s — My Statistics^n\w^n^n", menu)
	len += formatex(menu[len], charsmax(menu) - len, "\dRound %d:^n", g_RoundNumber)
	len += formatex(menu[len], charsmax(menu) - len, "  \rKills:\w %d   \rDeaths:\w %d^n", g_RoundStats[id][SP_ROUND_KILLS], g_RoundStats[id][SP_ROUND_DEATHS])
	len += formatex(menu[len], charsmax(menu) - len, "  \rHeadshots:\w %d   \rInfections:\w %d^n", g_RoundStats[id][SP_ROUND_HEADSHOTS], g_RoundStats[id][SP_ROUND_INFECTED])
	len += formatex(menu[len], charsmax(menu) - len, "  \rDamage Dealt:\w %d   \rDamage Taken:\w %d^n^n", g_RoundStats[id][SP_ROUND_DAMAGE_DONE], g_RoundStats[id][SP_ROUND_DAMAGE_TAKEN])
	len += formatex(menu[len], charsmax(menu) - len, "\dMap Total:^n")
	len += formatex(menu[len], charsmax(menu) - len, "  \rKills:\w %d   \rDeaths:\w %d^n", g_PlayerStats[id][SP_KILLS], g_PlayerStats[id][SP_DEATHS])
	len += formatex(menu[len], charsmax(menu) - len, "  \rHeadshots:\w %d   \rInfections:\w %d^n", g_PlayerStats[id][SP_HEADSHOTS], g_PlayerStats[id][SP_INFECTED])
	len += formatex(menu[len], charsmax(menu) - len, "  \rDamage Dealt:\w %d   \rDamage Taken:\w %d^n^n", g_PlayerStats[id][SP_DAMAGED_DONE], g_PlayerStats[id][SP_DAMAGED_TAKEN])
	len += formatex(menu[len], charsmax(menu) - len, "^n\r0.\w Back")

	new menuid = menu_create(menu, "menu_player_stats_handler")
	menu_additem(menuid, "\r0.\w Back")
	menu_setprop(menuid, MPROP_EXITNAME, "Exit")
	menu_display(id, menuid, g_MenuPage[id])
}

show_all_stats_menu(id, page)
{
	if (!is_user_connected(id))
		return

	g_MenuState[id] = MENU_ALL_STATS
	g_MenuPage[id] = page

	new menu[1024]
	new len = 0
	new name[MAX_NAME_LENGTH]
	new players[maxplayers], pcount, p
	new pname[MAX_NAME_LENGTH]

	len += formatex(menu[len], charsmax(menu) - len, "^n^n\yAll Players — Map Statistics^n\w^n^n")
	len += formatex(menu[len], charsmax(menu) - len, "\d#  Name                     K    D    HS  Inf  DmgD  DmgT^n")

	// Collect connected players
	new count = 0
	for (p = 1; p <= maxplayers; p++)
	{
		if (!is_user_connected(p))
			continue
		get_user_name(p, pname, charsmax(pname))
		// Truncate long names
		if (strlen(pname) > 22)
		{
			copy(pname, 22, pname)
			pname[21] = '^0'
		}
		len += formatex(menu[len], charsmax(menu) - len, "\d%d. %s  %3d  %3d  %3d  %3d  %4d  %4d^n",
			count + 1, pname,
			g_PlayerStats[p][SP_KILLS],
			g_PlayerStats[p][SP_DEATHS],
			g_PlayerStats[p][SP_HEADSHOTS],
			g_PlayerStats[p][SP_INFECTED],
			g_PlayerStats[p][SP_DAMAGED_DONE],
			g_PlayerStats[p][SP_DAMAGED_TAKEN])
		count++
	}

	if (count == 0)
	{
		len += formatex(menu[len], charsmax(menu) - len, "\dNo players connected^n^n")
	}

	len += formatex(menu[len], charsmax(menu) - len, "^n\r0.\w Back")

	new menuid = menu_create(menu, "menu_all_stats_handler")
	menu_additem(menuid, "\r0.\w Back")
	menu_setprop(menuid, MPROP_EXITNAME, "Exit")
	menu_display(id, menuid, g_MenuPage[id])
}

public menu_player_stats_handler(id, menuid, item)
{
	if (item == MENU_EXIT)
	{
		menu_destroy(menuid)
		g_MenuState[id] = MENU_NONE
		return PLUGIN_HANDLED
	}
	// Refresh
	show_player_stats_menu(id, g_MenuPage[id])
	return PLUGIN_HANDLED
}

public menu_all_stats_handler(id, menuid, item)
{
	if (item == MENU_EXIT)
	{
		menu_destroy(menuid)
		g_MenuState[id] = MENU_NONE
		return PLUGIN_HANDLED
	}
	// Refresh
	show_all_stats_menu(id, g_MenuPage[id])
	return PLUGIN_HANDLED
}

