input.oldString:
/*
 * Round & Player Statistics Manager for Zombie Plague 5.0.8a
 *
 * Tracks per-player and per-team statistics across rounds and maps.
 * Displays a MOTD window at the end of each round with stats for both
 * Terrorist (zombie) and Counter-Terrorist (human) sides.
 *
 * Natives for other plugins:
 *   zp_stats_get_user_kills(id)
 *   zp_stats_get_user_deaths(id)
 *   zp_stats_get_user_infected(id)
 *   zp_stats_get_user_damage_done(id)
 *   zp_stats_get_user_damage_taken(id)
 *   zp_stats_get_user_headshots(id)
 *   zp_stats_get_user_round_kills(id)
 *   zp_stats_get_user_round_deaths(id)
 *   zp_stats_get_user_round_infected(id)
 *   zp_stats_get_user_round_damage_done(id)
 *   zp_stats_get_user_round_damage_taken(id)
 *   zp_stats_get_user_round_headshots(id)
 *   zp_stats_get_team_round_kills(team)
 *   zp_stats_get_team_round_deaths(team)
 *   zp_stats_get_team_round_wins(team)
 *   zp_stats_get_round_phase()
 *   zp_stats_get_round_number()
 *   zp_stats_get_map_rounds()
 *   zp_stats_reset_user(id)
 *   zp_stats_reset_round()
 *   zp_stats_get_stats_count()
 *
 * Forwards for other plugins:
 *   zp_stats_fw_player_killed(victim, attacker, const weapon[], is_zombie_kill)
 *   zp_stats_fw_player_infected(id, attacker)
 *   zp_stats_fw_player_cured(id, attacker)
 *   zp_stats_fw_round_start()
 *   zp_stats_fw_round_end(winner_team)
 */

#include <amxmodx>
#include <amxmisc>
#include <cstrike>
#include <fakemeta>
#include <hamsandwich>
#include <cs_ham_bots_api>
#include <nvault>
#include <zp50_core>
#include <zp50_gamemodes>

#if AMXX_VERSION_NUM < 175
	#error "Requires AMX Mod X 1.75+"
#endif

// ─── Constants ───────────────────────────────────────────────────────────────
#define PLUGIN    "[ZP] Round Stats"
#define VERSION   "1.0.0"
#define AUTHOR    "Agnes/AI"

#define MAX_NAME_LENGTH     32
#define VAULT_KEY_PREFIX    "zp_rs_"
#define VAULT_FILE          "zp_round_stats"
#define PREFIX              "^x04[ZP Stats]^x01"

// ─── Enums ───────────────────────────────────────────────────────────────────
enum _:STATS_PLAYER
{
	SP_KILLS,
	SP_DEATHS,
	SP_INFECTED,
	SP_DAMAGED_DONE,
	SP_DAMAGED_TAKEN,
	SP_HEADSHOTS,
	SP_ROUND_KILLS,
	SP_ROUND_DEATHS,
	SP_ROUND_INFECTED,
	SP_ROUND_DAMAGE_DONE,
	SP_ROUND_DAMAGE_TAKEN,
	SP_ROUND_HEADSHOTS,
	SP_STATS_COUNT
}

enum _:STATS_TEAM
{
	ST_KILLS,
	ST_DEATHS,
	ST_ROUND_WINS,
	ST_STATS_COUNT
}

enum _:ROUND_PHASE
{
	RP_NONE = 0,
	RP_FREEZE,
	RP_PLAYING,
	RP_END
}

// ─── Globals ─────────────────────────────────────────────────────────────────
new g_PlayerStats[MAX_PLAYERS + 1][SP_STATS_COUNT]
new g_RoundStats[MAX_PLAYERS + 1][SP_STATS_COUNT]
new g_TeamRoundStats[2][ST_STATS_COUNT]

new g_RoundPhase
new g_RoundNumber
new g_MapRounds

new g_Vault
new g_HudSyncRound
new g_HudSyncMap

new g_PlayerUserId[MAX_PLAYERS + 1]

new g_fwPlayerKilled
new g_fwPlayerInfected
new g_fwPlayerCured
new g_fwRoundStart
new g_fwRoundEnd
new g_ForwardResult

// CVARs
new g_cvar_save_maps
new g_cvar_auto_reset
new g_cvar_count_self_death
new g_cvar_count_suicide
new g_cvar_track_world

// ─── Plugin init ─────────────────────────────────────────────────────────────
public plugin_init()
{
	register_plugin(PLUGIN, VERSION, AUTHOR)

	// Register events
	register_event("DeathMsg",   "event_death",      "a")
	register_event("SendAudio",  "event_round_end",  "a", "2=%!MRAD_terwin", "2=%!MRAD_ctwin", "2=%!MRAD_rounddraw")
	register_event("ResetHUD",   "event_reset_hud",  "b")
	register_event("TextMsg",    "event_textmsg",    "a")

	// Register Ham hooks
	RegisterHam(Ham_TakeDamage, "player", "Ham_TakeDamage_Post", 1)
	RegisterHamBots(Ham_TakeDamage, "Ham_TakeDamage_Post", 1)
	RegisterHam(Ham_Killed, "player", "Ham_Killed_Post", 1)
	RegisterHamBots(Ham_Killed, "Ham_Killed_Post", 1)
	RegisterHam(Ham_Spawn, "player", "Ham_Spawn_Post", 1)
	RegisterHamBots(Ham_Spawn, "Ham_Spawn_Post", 1)

	// Create HUD sync objects
	g_HudSyncRound = CreateHudSyncObj()
	g_HudSyncMap   = CreateHudSyncObj()

	// Initialize round state
	g_RoundPhase     = RP_NONE
	g_RoundNumber    = 0
	g_MapRounds      = 0

	// Open vault
	g_Vault = nvault_open(VAULT_FILE)
	if (g_Vault == INVALID_HANDLE)
		log_to_file("zp_round_stats.log", "[ZP RS] ERROR: Could not open vault '%s'", VAULT_FILE)
	else
		log_to_file("zp_round_stats.log", "[ZP RS] Vault opened successfully")

	log_to_file("zp_round_stats.log", "[ZP RS] plugin_init done")
}

public plugin_cfg()
{
	g_cvar_enabled          = create_cvar("zp_stats_enabled",       "1", FCVAR_SERVER, "Enable statistics tracking")
	g_cvar_log_level        = create_cvar("zp_stats_log_level",     "1", FCVAR_SERVER)
