// ─── Menu System ─────────────────────────────────────────────────────────────
enum _:MENU_STATE
{
	MENU_NONE = 0,
	MENU_PLAYER_STATS,
	MENU_ALL_STATS
}

new g_MenuState[MAX_PLAYERS + 1]
new g_MenuPage[MAX_PLAYERS + 1]

show_round_stats_menu()
{
	new menu[1024]
	new len = 0
	new name[MAX_NAME_LENGTH]
	new players[MAX_PLAYERS], pcount, p
	new pname[MAX_NAME_LENGTH]
	new totalKills = 0
	new totalDeaths = 0
	new totalInfected = 0
	new totalDamage = 0
	new totalHeadshots = 0

	// Calculate totals
	for (p = 1; p <= MAX_PLAYERS; p++)
	{
		if (!is_user_connected(p))
			continue
		totalKills    += g_PlayerStats[p][SP_KILLS]
		totalDeaths   += g_PlayerStats[p][SP_DEATHS]
		totalInfected += g_PlayerStats[p][SP_INFECTED]
		totalDamage   += g_PlayerStats[p][SP_DAMAGED_DONE]
		totalHeadshots += g_PlayerStats[p][SP_HEADSHOTS]
	}

	len += formatex(menu[len], charsmax(menu) - len, "<meta charset=\"utf-8\">")
	len += formatex(menu[len], charsmax(menu) - len, "<body bgcolor=\"#1a1a2e\" style=\"color:#eee; font-family:monospace; padding:20px;\">")
	len += formatex(menu[len], charsmax(menu) - len, "<h2 style=\"color:#e94560; text-align:center;\">[ZP] Round Statistics</h2>")
	len += formatex(menu[len], charsmax(menu) - len, "<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse:collapse; width:100%%; margin:10px 0;\">")
	len += formatex(menu[len], charsmax(menu) - len, "<tr style=\"background:#16213e;\">")
	len += formatex(menu[len], charsmax(menu) - len, "<th>#</th><th>Player</th><th>Kills</th><th>Deaths</th><th>HS</th><th>Infect</th><th>Dmg Done</th><th>Dmg Taken</th>")
	len += formatex(menu[len], charsmax(menu) - len, "</tr>")

	// Sort players by kills (bubble sort)
	new sortedPlayers[MAX_PLAYERS]
	new sortedKills[MAX_PLAYERS]
	new count = 0
	for (p = 1; p <= MAX_PLAYERS; p++)
	{
		if (!is_user_connected(p))
			continue
		sortedPlayers[count] = p
		sortedKills[count] = g_PlayerStats[p][SP_KILLS]
		count++
	}
	for (new i = 0; i < count - 1; i++)
	{
		for (new j = 0; j < count - 1 - i; j++)
		{
			if (sortedKills[j] < sortedKills[j + 1])
			{
				new temp = sortedKills[j]
				sortedKills[j] = sortedKills[j + 1]
				sortedKills[j + 1] = temp
				temp = sortedPlayers[j]
				sortedPlayers[j] = sortedPlayers[j + 1]
				sortedPlayers[j + 1] = temp
			}
		}
	}

	// Table rows
	for (p = 0; p < count; p++)
	{
		new pid = sortedPlayers[p]
		get_user_name(pid, pname, charsmax(pname))
		// Escape HTML
		replace(pname, charsmax(pname), "<", "&#60;")
		replace(pname, charsmax(pname), ">", "&#62;")
		new bgColor = (p % 2 == 0) ? "#1a1a2e" : "#16213e"
		len += formatex(menu[len], charsmax(menu) - len, "<tr style=\"background:%s;\">", bgColor)
		len += formatex(menu[len], charsmax(menu) - len, "<td>%d</td>", p + 1)
		len += formatex(menu[len], charsmax(menu) - len, "<td>%s</td>", pname)
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#0f0;\">%d</td>", g_PlayerStats[pid][SP_KILLS])
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#f55;\">%d</td>", g_PlayerStats[pid][SP_DEATHS])
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#ff0;\">%d</td>", g_PlayerStats[pid][SP_HEADSHOTS])
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#f0f;\">%d</td>", g_PlayerStats[pid][SP_INFECTED])
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#0ff;\">%d</td>", g_PlayerStats[pid][SP_DAMAGED_DONE])
		len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#fa0;\">%d</td>", g_PlayerStats[pid][SP_DAMAGED_TAKEN])
		len += formatex(menu[len], charsmax(menu) - len, "</tr>")
	}

	// Totals row
	len += formatex(menu[len], charsmax(menu) - len, "<tr style=\"background:#0f3460; font-weight:bold;\">")
	len += formatex(menu[len], charsmax(menu) - len, "<td>-</td><td>TOTAL</td>")
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#0f0;\">%d</td>", totalKills)
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#f55;\">%d</td>", totalDeaths)
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#ff0;\">%d</td>", totalHeadshots)
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#f0f;\">%d</td>", totalInfected)
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#0ff;\">%d</td>", totalDamage)
	len += formatex(menu[len], charsmax(menu) - len, "<td style=\"color:#fa0;\">-</td>")
	len += formatex(menu[len], charsmax(menu) - len, "</tr>")
	len += formatex(menu[len], charsmax(menu) - len, "</table>")

	// Round info
	len += formatex(menu[len], charsmax(menu) - len, "<div style=\"margin-top:15px; padding:10px; background:#16213e; border-radius:5px;\">")
	len += formatex(menu[len], charsmax(menu) - len, "<b>Round Info:</b><br>")
	len += formatex(menu[len], charsmax(menu) - len, "Round: %d / Map rounds: %d<br>", g_RoundNumber, g_MapRounds)
	len += formatex(menu[len], charsmax(menu) - len, "T (Zombies) wins: %d | CT (Humans) wins: %d", g_TeamRoundStats[0][ST_ROUND_WINS], g_TeamRoundStats[1][ST_ROUND_WINS])
	len += formatex(menu[len], charsmax(menu) - len, "</div>")

	len += formatex(menu[len], charsmax(menu) - len, "<div style=\"margin-top:10px; font-size:12px; color:#888; text-align:center;\">")
	len += formatex(menu[len], charsmax(menu) - len, "[ZP] Round Statistics v%s | AMX Mod X %s", VERSION, AMXX_VERSION_STR)
	len += formatex(menu[len], charsmax(menu) - len, "</div>")

	len += formatex(menu[len], charsmax(menu) - len, "</body></html>")

	// Show to all connected players
	new iPlayers[MAX_PLAYERS], iCount
	get_players(iPlayers, iCount)
	for (p = 0; p < iCount; p++)
	{
		show_motd(iPlayers[p], menu, sprintf("Round Stats - Round %d", g_RoundNumber))
	}
}

show_player_stats_menu(id, page)
