	len += formatex(menu[len], charsmax(menu) - len, "\dRound %d:^n", g_RoundNumber)
	len += formatex(menu[len], charsmax(menu) - len, "  \rKills:\w %d   \rDeaths:\w %d^n", g_RoundStats[id][SP_ROUND_KILLS], g_RoundStats[id][SP_ROUND_DEATHS])
	len += formatex(menu[len], charsmax(menu) - len, "  \rHeadshots:\w %d   \rInfections:\w %d^n", g_RoundStats[id][SP_ROUND_HEADSHOTS], g_RoundStats[id][SP_ROUND_INFECTED])
