color_chat_all(const msg[], {Float,Sql,Result,_}:...)
{
	new szMsg[256]
	vformat(szMsg, charsmax(szMsg), msg, 3)

	new iPlayers[MAX_PLAYERS], iCount
	get_players(iPlayers, iCount, "ch")

	for (new i = 0; i < iCount; i++)
	{
		new pid = iPlayers[i]
		message_begin(MSG_ONE, get_user_msgid("SayText"), _, pid)
		write_byte(0)
		write_string(szMsg)
		message_end()
	}
}

/*
 * Round & Player Statistics Manager for Zombie Plague 5.0.8a
 *
 * Tracks per-player and per-team statistics across rounds and maps.
 * Displays a MOTD window at the end of each round with stats for both
 * Terrorist (zombie) and Counter-Terrorist (human) sides.
 *
 * Natives for other plugins:
 *   zp_stats_get_user_kills(id)
 *   zp_stats_get_user_deaths(id)
 *   zp_stats_get_user_infected(id)
 *   zp_stats_get_user_damage_done(id)
 *   zp_stats_get_user_damage_taken(id)
 *   zp_stats_get_user_headshots(id)
 *   zp_stats_get_user_round_kills(id)
 *   zp_stats_get_user_round_deaths(id)
 *   zp_stats_get_user_round_infected(id)
 *   zp_stats_get_user_round_damage_done(id)
 *   zp_stats_get_user_round_damage_taken(id)
 *   zp_stats_get_user_round_headshots(id)
 *   zp_stats_get_team_round_kills(team)
 *   zp_stats_get_team_round_deaths(team)
 *   zp_stats_get_team_round_wins(team)
 *   zp_stats_get_round_phase()
 *   zp_stats_get_round_number()
 *   zp_stats_get_map_rounds()
 *   zp_stats_reset_user(id)
 *   zp_stats_reset_round()
 *   zp_stats_get_stats_count()
 *
 * Forwards for other plugins:
 *   zp_stats_fw_player_killed(victim, attacker, const weapon[], is_zombie_kill)
 *   zp_stats_fw_player_infected(id, attacker)
 *   zp_stats_fw_player_cured(id, attacker)
 *   zp_stats_fw_round_start()
 *   zp_stats_fw_round_end(winner_team)
 */

