		return

	g_MenuState[id] = MENU_ALL_STATS
	g_MenuPage[id] = page

	new menu[1024]
	new len = 0
	new players[MAX_PLAYERS], pcount, p
	new pname[MAX_NAME_LENGTH]

	len += formatex(menu[len], charsmax(menu) - len, "^n^n\yAll Players — Map Statistics^n\w^n^n")
